local ADDON, SM = ...

-- Geschichten für den Lore-Leser: je Zone/Stadt einige kurze Kapitel, in eigenen Worten
-- erzählt (Stand: die Welt um das Jahr 25 nach Öffnung des Dunklen Portals).
-- wiki = Seite im Warcraft Wiki (warcraft.wiki.gg/wiki/<wiki>) für "Mehr lesen".
-- Chinesische Clients bekommen die englischen Texte.
SM.LoreStories = {
    [1454] = { wiki = "Orgrimmar",
        de = {
            { h = "Ein Name für einen Freund", t = "Als die Schlacht am Berg Hyjal geschlagen war, führte Thrall sein Volk an die trockene Ostküste Kalimdors. Die neue Stadt bekam den Namen des Mannes, der ihn einst zum Kriegshäuptling gemacht hatte: Orgrim Schicksalshammer. Orgrim war bei der Befreiung der orcischen Lager gefallen - und hatte Thrall mit seinem letzten Atem seine schwarze Rüstung und seinen Hammer überlassen." },
            { h = "Gebaut in Rekordzeit", t = "Orgrimmar wuchs schnell. Goblins, Tauren, die Trolle der Dunkelspeere und der Halb-Oger Rexxar packten mit an. Dicke Mauern, schwere Tore und hohe Türme schützen die Stadt, im Rücken liegen die Berge - und ein Teil von Orgrimmar ist direkt in den roten Fels gehauen. Zentauren, Harpyien und Kobolde haben die Mauern geprüft. Gehalten haben sie." },
            { h = "Die Täler der Stadt", t = "Hinter dem Haupttor liegt das Tal der Stärke. Im Tal der Weisheit steht die Feste Grommash, benannt nach Grom Höllschrei, der die Orcs vom Blutfluch der Dämonen befreite, als er Mannoroth erschlug. Im Tal der Geister leben die Dunkelspeere, im Tal der Ehre trainieren die Krieger. Und tief unter der Kluft der Schatten, im Flammenschlund, haust ein Kult, der die dunklen Tage der Orcs zurückwill." },
        },
        en = {
            { h = "A name for a friend", t = "After the Battle of Mount Hyjal, Thrall led his people to the dry eastern coast of Kalimdor. The new city was named after the man who had once made him Warchief: Orgrim Doomhammer. Orgrim fell while freeing the orc internment camps - and with his last breath left Thrall his black armor and his hammer." },
            { h = "Built in record time", t = "Orgrimmar grew fast. Goblins, tauren, the Darkspear trolls and the half-ogre Rexxar all lent a hand. Thick walls, heavy gates and tall towers protect the city, the mountains guard its back - and part of Orgrimmar is carved straight into the red rock. Centaur, harpies and kobolds have tested those walls. They held." },
            { h = "The valleys of the city", t = "Behind the main gate lies the Valley of Strength. In the Valley of Wisdom stands Grommash Hold, named after Grom Hellscream, who freed the orcs from the demons' blood curse when he slew Mannoroth. The Darkspear live in the Valley of Spirits, warriors train in the Valley of Honor. And deep beneath the Cleft of Shadow, in Ragefire Chasm, a cult waits that wants the orcs' dark days back." },
        },
    },
    [1411] = { wiki = "Durotar",
        de = {
            { h = "Das Land eines Vaters", t = "Durotar trägt den Namen von Durotan, dem Häuptling des Frostwolfklans - Thralls Vater. Durotan wurde ermordet, als Thrall noch ein Säugling war. Der Junge wuchs bei Menschen auf, als Gladiator in einer Festung, und fand erst viel später zu seinem Volk. Das rote, harte Land ist sein Dank an einen Vater, den er nie kennenlernen durfte." },
            { h = "Prüfungen im Staub", t = "Junge Orcs und Trolle beginnen im Tal der Prüfungen. Wer sich bewährt, zieht weiter nach Klingenhügel. An der Küste liegt Sen'jin, das Dorf der Dunkelspeer-Trolle. Ihre Heimat, die Echoinseln vor der Küste, fiel an den Hexendoktor Zalazane, der seine eigenen Leute mit Voodoo unterwarf." },
            { h = "Eine Festung aus Kul Tiras", t = "An der Küste steht eine Festung, die nicht von Orcs gebaut wurde. Sie stammt aus der Zeit, als Admiral Daelin Prachtmeer mit seiner Flotte aus Kul Tiras Durotar angriff. Der Admiral fiel, doch einige seiner Soldaten harren hinter den Mauern bis heute aus - weit weg von zu Hause." },
        },
        en = {
            { h = "A father's land", t = "Durotar carries the name of Durotan, chieftain of the Frostwolf clan - Thrall's father. Durotan was murdered while Thrall was still a baby. The boy grew up among humans, as a gladiator in a fortress, and found his people only much later. This hard red land is his tribute to a father he never got to know." },
            { h = "Trials in the dust", t = "Young orcs and trolls begin in the Valley of Trials. Those who prove themselves move on to Razor Hill. On the coast lies Sen'jin, the village of the Darkspear trolls. Their home, the Echo Isles offshore, fell to the witch doctor Zalazane, who bent his own people to his will with voodoo." },
            { h = "A fortress from Kul Tiras", t = "On the coast stands a fortress that orcs did not build. It dates from the time when Admiral Daelin Proudmoore attacked Durotar with his fleet from Kul Tiras. The admiral fell, but some of his soldiers still hold out behind the walls - far from home." },
        },
    },
    [1456] = { wiki = "Thunder_Bluff",
        de = {
            { h = "Eine Stadt auf den Tafelbergen", t = "Donnerfels steht hoch über Mulgore auf steilen Tafelbergen. Cairne Bluthuf, der Großhäuptling der Tauren, einte hier sein Volk, das lange als Nomaden vor den Zentauren fliehen musste. Mit Thralls Hilfe fanden die Tauren endlich ein Zuhause - und Cairne schloss sich der Horde an." },
            { h = "Brücken und Aufzüge", t = "Die Anhöhen der Stadt sind durch schwankende Hängebrücken verbunden, und große Aufzüge aus Holz bringen Besucher vom Boden nach oben. Wer feindlich gesinnt kommt, muss erst einmal hinaufkommen. Oben flattern Totems und Zelte im Wind, und Windreiter tragen Reisende in die Ferne." },
            { h = "Älteste, Geister und Jäger", t = "Auf der Anhöhe der Ältesten lehren die Druiden um Hamuul Runentotem. Auf der Anhöhe der Geister wohnen die Schamanen - und Magatha Grimmtotem, deren Klan Cairne nicht ganz so treu ist, wie es scheint. Die Anhöhe der Jäger gehört denen, die mit Bogen und Tier durch Mulgore streifen." },
        },
        en = {
            { h = "A city on the mesas", t = "Thunder Bluff rises high above Mulgore on steep mesas. Cairne Bloodhoof, high chieftain of the tauren, united his people here after they had long wandered as nomads, fleeing the centaur. With Thrall's help the tauren finally found a home - and Cairne joined the Horde." },
            { h = "Bridges and lifts", t = "The rises of the city are linked by swaying rope bridges, and large wooden lifts carry visitors up from the ground. Anyone who comes with ill intent has to get up there first. Up top, totems and tents flutter in the wind, and wind riders carry travelers far away." },
            { h = "Elders, spirits and hunters", t = "On the Elder Rise the druids teach around Hamuul Runetotem. The shamans live on the Spirit Rise - and so does Magatha Grimtotem, whose clan is not quite as loyal to Cairne as it seems. The Hunter Rise belongs to those who roam Mulgore with bow and beast." },
        },
    },
    [1412] = { wiki = "Mulgore",
        de = {
            { h = "Grüne Ebenen", t = "Mulgore ist das grüne Herz der Tauren: weite Wiesen, sanfte Hügel, Wasserfälle und Herden von Ebenenschreitern. Junge Tauren beginnen im Camp Narache und ziehen dann zum Dorf der Bluthufe." },
            { h = "Die Roten Felsen", t = "Die Roten Felsen sind den Tauren heilig. Hier ruhen ihre Ahnen, und hierher kommen sie, um ihrer zu gedenken. Wer hier oben steht, blickt über das ganze Tal - in WoW Forever reicht der Blick bei klarem Wetter sogar bis zum fernen Hyjal." },
            { h = "Ungebetene Gäste", t = "Nicht alle in Mulgore sind willkommen. Die Goblins der Venture Company holzen Bäume ab und graben nach Erz, und in ihren Höhlen hausen Gnolle. Die Tauren wehren sich - meist mit Hilfe frischer Abenteurer." },
        },
        en = {
            { h = "Green plains", t = "Mulgore is the green heart of the tauren: wide meadows, gentle hills, waterfalls and herds of plainstriders. Young tauren begin at Camp Narache and then move on to Bloodhoof Village." },
            { h = "Red Rocks", t = "Red Rocks is sacred to the tauren. Their ancestors rest here, and here they come to remember them. Standing up there, you look over the whole valley - in WoW Forever, on a clear day, the view even reaches distant Hyjal." },
            { h = "Uninvited guests", t = "Not everyone in Mulgore is welcome. The goblins of the Venture Company cut down trees and dig for ore, and gnolls lurk in their caves. The tauren fight back - usually with the help of fresh adventurers." },
        },
    },
    [1458] = { wiki = "Undercity",
        de = {
            { h = "Eine Stadt unter einer Stadt", t = "Über Unterstadt liegen die Ruinen von Lordaeron, einst die Hauptstadt eines stolzen Königreichs. Im Thronsaal tötete Prinz Arthas seinen eigenen Vater, König Terenas, und die Seuche fraß das Land. Unter den Ruinen lagen Gruften, Katakomben und Kanäle - dort bauten die Verlassenen ihre Stadt." },
            { h = "Die Verlassenen", t = "Die Verlassenen waren Untote, die sich von der Geißel losrissen. Ihre Anführerin Sylvanas Windläufer, einst Waldläufergeneralin von Quel'Thalas, will keinen König mehr über sich. Die Verlassenen gehören zur Horde - doch viele dort trauen ihnen nicht." },
            { h = "Grüne Kanäle", t = "Durch Unterstadt fließt grün leuchtender Schleim. In ihren Laboren arbeitet die Königliche Apothekervereinigung an neuen Seuchen - offiziell gegen die Geißel. Wer genauer hinsieht, fragt sich, gegen wen sonst noch." },
        },
        en = {
            { h = "A city beneath a city", t = "Above the Undercity lie the ruins of Lordaeron, once the capital of a proud kingdom. In its throne room Prince Arthas killed his own father, King Terenas, and the plague devoured the land. Below the ruins lay crypts, catacombs and sewers - and there the Forsaken built their city." },
            { h = "The Forsaken", t = "The Forsaken are undead who broke free of the Scourge. Their leader, Sylvanas Windrunner, once Ranger-General of Quel'Thalas, wants no king above her ever again. The Forsaken belong to the Horde - but many there do not trust them." },
            { h = "Green canals", t = "Glowing green ooze flows through the Undercity. In their laboratories the Royal Apothecary Society works on new plagues - officially against the Scourge. Look closer, and you wonder who else they might be meant for." },
        },
    },
    [1420] = { wiki = "Tirisfal_Glades",
        de = {
            { h = "Ein Wald im Zwielicht", t = "Tirisfal war einst fruchtbares Bauernland nahe der Hauptstadt Lordaeron. Heute liegt ein grauer Schleier über den Lichtungen, die Felder sind von der Seuche verdorben, und in den Mühlen der Familie Agamand wandeln die Toten." },
            { h = "Brill", t = "Im Dorf Brill haben die Verlassenen ein Gasthaus, einen Stall mit Skelettpferden und vieles, was Lebende eher gruselig finden. Für die Verlassenen ist es einfach ein Stück Zuhause." },
            { h = "Das Scharlachrote Kloster", t = "Im Nordosten Tirisfals erhebt sich das Scharlachrote Kloster. Der Scharlachrote Kreuzzug hasst alles Untote - und traut auch sonst kaum jemandem. Seine Mönche und Ritter halten das Kloster mit fanatischer Härte." },
        },
        en = {
            { h = "A forest in twilight", t = "Tirisfal was once fertile farmland near the capital of Lordaeron. Today a grey haze hangs over the glades, the fields are spoiled by the plague, and the dead walk in the Agamand family's mills." },
            { h = "Brill", t = "In the village of Brill the Forsaken keep an inn, a stable of skeletal horses and much else that the living find a little creepy. For the Forsaken it is simply a piece of home." },
            { h = "The Scarlet Monastery", t = "In the northeast of Tirisfal rises the Scarlet Monastery. The Scarlet Crusade hates everything undead - and barely trusts anyone else. Its monks and knights hold the monastery with fanatical zeal." },
        },
    },
    [1453] = { wiki = "Stormwind_City",
        de = {
            { h = "Wiederaufgebaut aus Trümmern", t = "Im Ersten Krieg zerstörte die Horde Sturmwind. Nach dem Zweiten Krieg bauten Steinmetze die Stadt neu auf - prächtiger als zuvor. Doch die Adligen weigerten sich, sie zu bezahlen. Ihr Anführer Edwin van Cleef ging mit seinen Leuten nach Westfall und gründete die Defiasbruderschaft." },
            { h = "Ein Thron ohne König", t = "König Varian Wrynn ist verschwunden, niemand weiß, wohin. An seiner Stelle regiert Hochlord Bolvar Fordragon für den jungen Prinzen Anduin. Am Hof hat eine geheimnisvolle Beraterin, Lady Prestor, erstaunlich viel Einfluss." },
            { h = "Ein Gang durch die Stadt", t = "Über die Brücke im Tal der Helden kommt man in den Handelsdistrikt. Die Kathedrale des Lichts ist das Herz des Glaubens, im Magierviertel funkelt es an jeder Ecke, in der Altstadt geht es rauer zu. Und von der Burg Sturmwind aus blickt man über Dächer und Kanäle. In WoW Forever wurde Sturmwind neu gezeichnet - schau dich also ruhig neu um." },
        },
        en = {
            { h = "Rebuilt from the rubble", t = "In the First War the Horde destroyed Stormwind. After the Second War, stonemasons rebuilt the city - grander than before. But the nobles refused to pay them. Their leader, Edwin VanCleef, took his people to Westfall and founded the Defias Brotherhood." },
            { h = "A throne without a king", t = "King Varian Wrynn has vanished, and no one knows where. In his place Highlord Bolvar Fordragon rules for the young Prince Anduin. At court, a mysterious advisor, Lady Prestor, holds a surprising amount of influence." },
            { h = "A walk through the city", t = "Across the bridge in the Valley of Heroes you reach the Trade District. The Cathedral of Light is the heart of the faith, the Mage Quarter sparkles on every corner, and things get rougher in Old Town. From Stormwind Keep you look out over roofs and canals. In WoW Forever, Stormwind has been redrawn - so feel free to explore it anew." },
        },
    },
    [1429] = { wiki = "Elwynn_Forest",
        de = {
            { h = "Der erste Schritt", t = "In der Abtei von Nordhain beginnen viele junge Menschen ihr Abenteuer. Die Mönche und Ritter dort geben ihnen erste Aufgaben - meist gegen Wölfe, Kobolde und Banditen, die sich viel zu nah an die Abtei wagen." },
            { h = "Goldhain", t = "Goldhain ist ein kleines Dorf an der Straße nach Sturmwind. Im Gasthaus „Zur Höhle des Löwen“ treffen sich Abenteurer aller Art, und auf dem Platz davor ist eigentlich immer etwas los." },
            { h = "Ruhige Wälder, unruhige Zeiten", t = "Elwynn wirkt friedlich: Bäche, Felder, Holzfällerlager. Doch die Defias treiben sich auch hier herum, und die Kobolde in den Minen hüten ihre Kerzen mit Leidenschaft. „Ihr nicht nehmen Kerze!“ hat schon viele Helden zum Schmunzeln gebracht." },
        },
        en = {
            { h = "The first step", t = "At Northshire Abbey many young humans begin their adventure. The monks and knights there give them their first tasks - usually against wolves, kobolds and bandits who come far too close to the abbey." },
            { h = "Goldshire", t = "Goldshire is a small village on the road to Stormwind. At the Lion's Pride Inn adventurers of every kind meet, and the square in front of it is almost never quiet." },
            { h = "Quiet woods, restless times", t = "Elwynn looks peaceful: streams, fields, logging camps. But the Defias roam here too, and the kobolds in the mines guard their candles with passion. \"You no take candle!\" has made many a hero smile." },
        },
    },
    [1455] = { wiki = "Ironforge",
        de = {
            { h = "Eine Stadt im Berg", t = "Eisenschmiede ist tief in den Berg gehauen, mitten in Khaz Modan. Hier herrscht König Magni Bronzebart. Im Zentrum glüht die Große Schmiede, deren Hitze und Lärm man in der ganzen Stadt spürt." },
            { h = "Drei Hämmer", t = "Einst stritten drei Zwergenklans um Eisenschmiede: die Bronzebarts, die Wildhämmer und die Dunkeleisenzwerge. Im Krieg der Drei Hämmer rief der Zauberer-Thain Thaurissan den Feuerlord Ragnaros herbei - und verwüstete damit das Land, das heute Brennende Steppe und Sengende Schlucht heißt." },
            { h = "Forscher und Tüftler", t = "In der Halle der Forscher sammelt die Forscherliga, was sie in alten Ruinen findet. In der Tüftlerstadt leben die Gnome, seit sie ihre Stadt Gnomeregan verloren haben. Und die Tiefenbahn bringt Reisende unter der Erde bis nach Sturmwind." },
        },
        en = {
            { h = "A city inside the mountain", t = "Ironforge is carved deep into the mountain, in the heart of Khaz Modan. King Magni Bronzebeard rules here. At its center glows the Great Forge, whose heat and noise you can feel all over the city." },
            { h = "Three hammers", t = "Long ago three dwarven clans fought over Ironforge: the Bronzebeards, the Wildhammers and the Dark Irons. In the War of the Three Hammers the sorcerer-thane Thaurissan summoned the Firelord Ragnaros - and laid waste to the land known today as the Burning Steppes and the Searing Gorge." },
            { h = "Explorers and tinkerers", t = "In the Hall of Explorers the Explorers' League collects what it finds in ancient ruins. The gnomes live in Tinker Town since they lost their city of Gnomeregan. And the Deeprun Tram carries travelers underground all the way to Stormwind." },
        },
    },
    [1426] = { wiki = "Dun_Morogh",
        de = {
            { h = "Schnee und Bier", t = "Dun Morogh ist kalt, verschneit und gastfreundlich. Junge Zwerge und Gnome beginnen im Tal von Kaltgrat, und im Dorf Kharanos braut die Familie Donnerbräu ein Bier, für das man gern einen Umweg macht." },
            { h = "Gnomeregan", t = "Gnomeregan war die Stadt der Gnome - bis Troggs aus der Tiefe sie überrannten. Auf Rat ihres Robogenieurs Thermadraht setzten die Gnome eine verheerende Strahlung gegen die Eindringlinge ein. Viele Gnome starben selbst daran. Erst später zeigte sich, dass Thermadraht sie verraten hatte." },
            { h = "Das Tor zum Berg", t = "Der Weg nach Eisenschmiede führt durch ein gewaltiges Tor, das von steinernen Zwergenkriegern bewacht wird. Wer davorsteht, versteht, warum die Zwerge stolz auf ihre Baukunst sind." },
        },
        en = {
            { h = "Snow and beer", t = "Dun Morogh is cold, snowy and welcoming. Young dwarves and gnomes begin in Coldridge Valley, and in the village of Kharanos the Thunderbrew family brews a beer worth a detour." },
            { h = "Gnomeregan", t = "Gnomeregan was the city of the gnomes - until troggs from the deep overran it. On the advice of their Mekgineer Thermaplugg, the gnomes unleashed devastating radiation against the invaders. Many gnomes died from it themselves. Only later did it turn out that Thermaplugg had betrayed them." },
            { h = "The gate to the mountain", t = "The road to Ironforge leads through a massive gate guarded by stone dwarven warriors. Standing in front of it, you understand why the dwarves are proud of their craft." },
        },
    },
    [1457] = { wiki = "Darnassus",
        de = {
            { h = "Eine Stadt in der Krone", t = "Darnassus liegt hoch oben in der Krone des Weltenbaums Teldrassil. Weiße Steinbauten, ruhige Teiche und alte Bäume prägen die Stadt der Nachtelfen. Unten an den Wurzeln liegt Rut'theran, von dort bringt ein Portal Besucher hinauf." },
            { h = "Der Tempel des Mondes", t = "Im Tempel des Mondes dienen die Priesterinnen der Mondgöttin Elune. Ihre Hohepriesterin ist Tyrande Wisperwind, die die Nachtelfen auch im Krieg anführt. Das Licht im Tempel ist gedämpft, das Wasser glitzert - ein Ort zum Leisesein." },
            { h = "Die Druiden", t = "In der Enklave des Cenarius lehren die Druiden. Ihr Erzdruide Fandral Hirschhaupt hat Teldrassil gepflanzt. Manche Nachtelfen fragen sich leise, ob dieser Baum je den Segen bekommen hat, den der alte Weltenbaum einst hatte." },
        },
        en = {
            { h = "A city in the crown", t = "Darnassus lies high in the crown of the World Tree Teldrassil. White stone buildings, calm ponds and ancient trees shape the city of the night elves. Down at the roots lies Rut'theran, from where a portal carries visitors up." },
            { h = "The Temple of the Moon", t = "In the Temple of the Moon the priestesses serve the moon goddess Elune. Their high priestess is Tyrande Whisperwind, who also leads the night elves in war. The light in the temple is soft, the water glitters - a place for quiet." },
            { h = "The druids", t = "In the Cenarion Enclave the druids teach. Their Archdruid, Fandral Staghelm, planted Teldrassil. Some night elves quietly wonder whether this tree ever received the blessing the old World Tree once had." },
        },
    },
    [1438] = { wiki = "Teldrassil",
        de = {
            { h = "Ein neuer Weltenbaum", t = "Nach der Schlacht am Berg Hyjal verloren die Nachtelfen ihre Unsterblichkeit. Um sie zurückzugewinnen, pflanzten die Druiden vor der Küste der Dunkelküste einen neuen Weltenbaum: Teldrassil. Er wuchs gewaltig - groß genug, dass ein ganzes Land auf seinen Ästen Platz fand." },
            { h = "Schattenhain", t = "Junge Nachtelfen beginnen in Schattenhain, einem stillen Ort voller Mondlicht. Doch selbst hier stimmt nicht alles: Manche Tiere und Furbolgs wirken seltsam unruhig, als ob etwas im Baum nicht in Ordnung wäre." },
            { h = "Unter dem Blätterdach", t = "In Teldrassil wechseln sich Seen, Lichtungen und Höhlen ab. Wer nach oben schaut, sieht keinen Himmel, sondern ein endloses Dach aus Blättern. Gerade in der Dämmerung ist das Licht hier besonders schön." },
        },
        en = {
            { h = "A new World Tree", t = "After the Battle of Mount Hyjal the night elves lost their immortality. To win it back, the druids planted a new World Tree off the coast of Darkshore: Teldrassil. It grew enormous - large enough for a whole land to fit on its branches." },
            { h = "Shadowglen", t = "Young night elves begin in Shadowglen, a quiet place full of moonlight. But even here not everything is right: some animals and furbolgs seem strangely restless, as if something in the tree were not quite well." },
            { h = "Under the canopy", t = "In Teldrassil, lakes, glades and caves follow one another. Looking up, you see no sky but an endless roof of leaves. Especially at dusk the light here is beautiful." },
        },
    },
    [1436] = { wiki = "Westfall",
        de = {
            { h = "Die Kornkammer, die verdorrte", t = "Westfall war einst die Kornkammer Sturmwinds. Heute liegen viele Höfe verlassen da. Banditen, wilde Tiere und Erntegolems, die eigentlich den Bauern helfen sollten, machen das Land unsicher." },
            { h = "Die Defias", t = "Hinter vielen Überfällen steckt die Defiasbruderschaft - die Steinmetze, die Sturmwind wieder aufbauten und nie bezahlt wurden. Unter dem verlassenen Dorf Mondbruch, in den Todesminen, baut ihr Anführer Edwin van Cleef an einem eigenen Schiff." },
            { h = "Die Volksmiliz", t = "Weil Sturmwind kaum hilft, hat Gryan Starkmantel auf der Späherkuppe die Volksmiliz gegründet. Einfache Leute verteidigen hier ihre Heimat - und sind froh über jede helfende Hand." },
        },
        en = {
            { h = "The breadbasket that withered", t = "Westfall was once Stormwind's breadbasket. Today many farms stand abandoned. Bandits, wild animals and harvest golems that were meant to help the farmers make the land unsafe." },
            { h = "The Defias", t = "Behind many raids stands the Defias Brotherhood - the stonemasons who rebuilt Stormwind and were never paid. Beneath the abandoned village of Moonbrook, in the Deadmines, their leader Edwin VanCleef is building a ship of his own." },
            { h = "The People's Militia", t = "Because Stormwind barely helps, Gryan Stoutmantle founded the People's Militia at Sentinel Hill. Ordinary people defend their home here - and are glad of every helping hand." },
        },
    },
    [1431] = { wiki = "Duskwood",
        de = {
            { h = "Ein Wald ohne Morgen", t = "Im Dämmerwald wird es nie richtig hell. Man erzählt, der nahe Turm Karazhan habe seinen Schatten über den Wald gelegt. In WoW Forever zieht nachts Bodennebel zwischen den Bäumen hindurch - schöner und unheimlicher als je zuvor." },
            { h = "Die Nachtwache", t = "Das Städtchen Dunkelhain wird von der Nachtwache beschützt, freiwilligen Wächtern, die jede Nacht gegen Untote, Worgen und Spinnen ausrücken. Ohne sie gäbe es Dunkelhain längst nicht mehr." },
            { h = "Der Rabenhügel", t = "Auf dem Friedhof am Rabenhügel finden die Toten keine Ruhe. Und nicht jeder freundliche Einsiedler im Wald ist so harmlos, wie er beim Tee wirkt - wer in Dunkelhain genau zuhört, erfährt mehr." },
        },
        en = {
            { h = "A forest without a morning", t = "In Duskwood it never really gets light. People say the nearby tower of Karazhan has cast its shadow over the forest. In WoW Forever, ground fog drifts between the trees at night - more beautiful and eerier than ever." },
            { h = "The Night Watch", t = "The little town of Darkshire is protected by the Night Watch, volunteer guards who head out every night against undead, worgen and spiders. Without them Darkshire would be long gone." },
            { h = "Raven Hill", t = "At the cemetery on Raven Hill the dead find no rest. And not every friendly hermit in the woods is as harmless as he seems over tea - listen closely in Darkshire, and you will learn more." },
        },
    },
    [1440] = { wiki = "Ashenvale",
        de = {
            { h = "Der alte Wald", t = "Eschental ist uralter Wald der Nachtelfen, voller Mondlicht, Lichtungen und stiller Seen. In WoW Forever fallen Lichtstrahlen durch das Blätterdach und Nebel liegt über dem Boden - einer der schönsten Orte für ein Foto." },
            { h = "Holz für die Horde", t = "Die Horde schlägt hier Holz, und die Nachtelfen verteidigen jeden Baum. Der Streit ist alt: Schon Grom Höllschreis Kriegshymnenklan fällte hier Bäume, und der Halbgott Cenarius stellte sich ihm entgegen - und fiel." },
            { h = "Die Schlucht des Dämons", t = "In einer Schlucht im Eschental erschlug Grom Höllschrei den Dämon Mannoroth und befreite die Orcs vom Blutfluch - und starb dabei selbst. Die Orcs ehren ihn dort bis heute mit einem Denkmal." },
        },
        en = {
            { h = "The ancient forest", t = "Ashenvale is the ancient forest of the night elves, full of moonlight, glades and quiet lakes. In WoW Forever, light rays fall through the canopy and mist lies on the ground - one of the most beautiful places for a picture." },
            { h = "Wood for the Horde", t = "The Horde cuts timber here, and the night elves defend every tree. The quarrel is old: Grom Hellscream's Warsong clan already felled trees here, and the demigod Cenarius stood against him - and fell." },
            { h = "The demon's canyon", t = "In a canyon in Ashenvale, Grom Hellscream slew the demon Mannoroth and freed the orcs from the blood curse - dying himself in the process. The orcs still honor him there with a monument." },
        },
    },
    [1413] = { wiki = "The_Barrens",
        de = {
            { h = "Weites Land", t = "Das Brachland ist eine endlose Savanne aus Gras, Staub und Dornenbüschen. In WoW Forever reicht der Blick durch den neuen Nebel bis nach Durotar und Azshara - an klaren Tagen wirkt das Land noch größer." },
            { h = "Das Wegekreuz", t = "Am Wegekreuz treffen sich die Straßen der Horde. Händler, Reisende und Abenteurer kommen hier vorbei, und es gibt immer jemanden, der Hilfe sucht. Weiter östlich liegt Ratschet, ein Goblinhafen, in dem jeder Geschäfte macht, der zahlt." },
            { h = "Die Oasen", t = "Die Oasen im Brachland verändern sich: Druiden des Giftzahns träumen in den Höhlen des Wehklagens einen Traum, der das Land grün machen sollte - doch der Traum ist zum Albtraum geworden." },
        },
        en = {
            { h = "Wide land", t = "The Barrens are an endless savanna of grass, dust and thorn bushes. In WoW Forever, through the new fog, the view reaches all the way to Durotar and Azshara - on clear days the land feels even bigger." },
            { h = "The Crossroads", t = "At the Crossroads the roads of the Horde meet. Traders, travelers and adventurers pass through, and there is always someone looking for help. Further east lies Ratchet, a goblin port where anyone does business who pays." },
            { h = "The oases", t = "The oases of the Barrens are changing: the Druids of the Fang dream a dream in the Wailing Caverns that was meant to make the land green - but the dream has turned into a nightmare." },
        },
    },
    -- Zonen für Stufe 10-40 (die Endgebiete folgen)
    [1421] = { wiki = "Silverpine_Forest",
        de = {
            { h = "Hinter dem Wall", t = "Der Silberwald ist dunkel, nass und still. Im Süden versperrt der Graumähnenwall den Weg nach Gilneas: König Genn Graumähne ließ ihn bauen und kehrte der Allianz den Rücken. Was hinter der Mauer geschieht, weiß hier niemand so genau." },
            { h = "Arugals Fehler", t = "Um die Geißel aufzuhalten, holte der Erzmagier Arugal aus Dalaran die Worgen in diese Welt. Doch die Wolfsbestien gehorchten nicht lange. Arugal verlor den Verstand und verschanzt sich mit ihnen in der Burg Schattenfang. In einem Dorf im Süden verwandeln sich die Bewohner nachts selbst in Worgen." },
            { h = "Das Grabmal", t = "Die Verlassenen haben am Grabmal ihren Stützpunkt im Wald. Von hier aus kämpfen sie gegen Worgen, gegen die Geißel und gegen Magier aus Dalaran, die sich in einem Dorf am Waldrand eingerichtet haben. Wer hier lebt, ist meist schon einmal gestorben." },
        },
        en = {
            { h = "Behind the wall", t = "Silverpine Forest is dark, damp and quiet. To the south, the Greymane Wall blocks the road to Gilneas: King Genn Greymane had it built and turned his back on the Alliance. What happens behind the wall, nobody here really knows." },
            { h = "Arugal's mistake", t = "To stop the Scourge, the archmage Arugal of Dalaran brought the worgen into this world. But the wolf beasts did not obey for long. Arugal lost his mind and hides with them in Shadowfang Keep. In a village to the south, the villagers themselves turn into worgen at night." },
            { h = "The Sepulcher", t = "The Forsaken hold the Sepulcher, their base in the forest. From here they fight worgen, the Scourge and the mages of Dalaran who have settled in a village at the forest's edge. Most of the people living here have already died once." },
        },
    },
    [1439] = { wiki = "Darkshore",
        de = {
            { h = "Hafen Auberdine", t = "Auberdine ist das Tor der Nachtelfen zur Welt: Von hier fahren Schiffe hinüber nach Teldrassil und über das Meer zum Hafen von Menethil. Schildwachen halten Wache, an den Stegen warten Reisende, und abends liegt Nebel über dem Wasser." },
            { h = "Eine Klinge im Boden", t = "Im Süden der Küste steckt eine riesige Gleve im Boden. Wem sie einst gehörte, erzählt jede Sage anders. Heute versammeln sich dort Kultisten des Schattenhammers - und niemand weiß genau, was sie an diesem Ort suchen." },
            { h = "Was die Küste verbirgt", t = "Weiter nördlich liegen Ruinen aus der Zeit der Hochgeborenen, halb vom Meer verschluckt. Die Forscherliga der Zwerge gräbt an der Küste nach Spuren alter Zeiten. Und die Furbolgs, einst friedliche Nachbarn der Nachtelfen, sind von einer Verderbnis befallen und greifen jeden an, der ihnen zu nahe kommt." },
        },
        en = {
            { h = "Auberdine harbor", t = "Auberdine is the night elves' gate to the world: ships sail from here to Teldrassil and across the sea to Menethil Harbor. Sentinels keep watch, travelers wait on the piers, and in the evening mist lies over the water." },
            { h = "A blade in the ground", t = "In the south of the coast, a giant glaive is stuck in the earth: the Master's Glaive. Every legend tells a different story of who once wielded it. Today, cultists of the Twilight's Hammer gather there - and no one quite knows what they are looking for." },
            { h = "What the coast hides", t = "Further north lie ruins from the age of the Highborne, half swallowed by the sea. The dwarves of the Explorers' League dig along the coast for traces of ancient times. And the furbolgs, once peaceful neighbors of the night elves, have fallen to corruption and attack anyone who comes too close." },
        },
    },
    [1432] = { wiki = "Loch_Modan",
        de = {
            { h = "Ein See von Zwergenhand", t = "Den Loch Modan gibt es so nur, weil die Zwerge ihn aufgestaut haben. Der gewaltige Damm im Norden hält das Wasser zurück und ist der Stolz der Baumeister von Eisenschmiede. Angler sitzen an seinen Ufern, und an klaren Tagen glitzert der See bis weit in die Berge." },
            { h = "Thelsamar", t = "Thelsamar ist ein freundliches Zwergendorf mit Gasthaus, Schmiede und Greifenmeister. Die Gebirgsjäger von Eisenschmiede schützen das Tal: vor Troggs, die aus der Tiefe heraufkommen, vor Kobolden in den Minen und vor den Dunkeleisenzwergen, die immer wieder Ärger machen." },
            { h = "Spuren der Titanen", t = "Die Forscherliga hat am Loch Modan eine Ausgrabung begonnen. Die Zwerge wollen wissen, woher ihr Volk stammt - und viele glauben, die Antwort führt zu den Titanen. Eine heiße Spur liegt weiter südlich im Ödland: das uralte Gewölbe Uldaman." },
        },
        en = {
            { h = "A lake made by dwarves", t = "Loch Modan only looks the way it does because the dwarves dammed it. The mighty dam in the north holds back the water and is the pride of Ironforge's builders. Anglers sit along its shores, and on clear days the lake glitters far into the mountains." },
            { h = "Thelsamar", t = "Thelsamar is a friendly dwarven village with an inn, a smithy and a gryphon master. The Mountaineers of Ironforge protect the valley: from troggs climbing up from the depths, from kobolds in the mines, and from the Dark Iron dwarves who keep stirring up trouble." },
            { h = "Traces of the titans", t = "The Explorers' League has started a dig at Loch Modan. The dwarves want to know where their people came from - and many believe the answer leads to the titans. A hot trail lies further south in the Badlands: the ancient vault of Uldaman." },
        },
    },
    [1433] = { wiki = "Redridge_Mountains",
        de = {
            { h = "Seenhain", t = "Seenhain liegt am Immerstillen See, mit einer Brücke, einem Gasthaus und Booten am Ufer. Fischer, Holzfäller und Bauern leben hier - eigentlich ein ruhiger Ort. Doch seit Jahren kommt das Dorf nicht zur Ruhe." },
            { h = "Briefe nach Sturmwind", t = "Magistrat Solomon schreibt Brief um Brief nach Sturmwind und bittet um Soldaten. Doch die Armee des Königreichs ist anderswo gebunden, und Hilfe kommt kaum. Also stützt sich Seenhain auf seine Wachen - und auf Abenteurer, die zufällig vorbeikommen." },
            { h = "Feinde aus den Bergen", t = "Aus der Brennenden Steppe im Norden kommen die Orcs des Schwarzfelsclans. Sie haben eine alte Festung im Tal besetzt und plündern die Höfe, dazu streifen Gnolle durch die Hügel. Das Rotkammgebirge ist schön - aber hier geht man besser nicht allein spazieren." },
        },
        en = {
            { h = "Lakeshire", t = "Lakeshire lies on Lake Everstill, with a bridge, an inn and boats along the shore. Fishermen, loggers and farmers live here - really a peaceful place. But for years now the village has found no peace." },
            { h = "Letters to Stormwind", t = "Magistrate Solomon writes letter after letter to Stormwind asking for soldiers. But the kingdom's army is tied up elsewhere, and help rarely comes. So Lakeshire relies on its guards - and on adventurers who happen to pass by." },
            { h = "Enemies from the mountains", t = "From the Burning Steppes to the north come the orcs of the Blackrock clan. They have taken an old keep in the valley and raid the farms, and gnolls roam the hills as well. Redridge is beautiful - but it is better not to go walking here alone." },
        },
    },
    [1442] = { wiki = "Stonetalon_Mountains",
        de = {
            { h = "Der Gipfel der Druiden", t = "Hoch oben auf dem Steinkrallengipfel wächst ein alter, grüner Wald, und dort wachen die Druiden der Nachtelfen. Sie hüten das Gleichgewicht der Natur in diesen Bergen - und sehen mit Sorge, was weiter unten geschieht." },
            { h = "Kreischende Sägen", t = "Die Goblins der Venture Co. holzen die Wälder ab, so schnell ihre Schredder können. Wo früher Bäume standen, liegen heute Stümpfe, Schutt und Öl. Ganze Täler sind kahl - und die Goblins zählen dabei nur ihr Gold." },
            { h = "Harpyien und Tauren", t = "In den Felsen nisten Harpyien, und der Grimmtotem-Klan der Tauren geht hier eigene Wege - nicht immer friedlich. Die Horde hat in den Bergen einen Rastplatz, die Nachtelfen ihren Gipfel. Und ein Pfad tief durch den Berg führt hinüber ins Eschental." },
        },
        en = {
            { h = "The druids' peak", t = "High up on Stonetalon Peak grows an old, green forest, and the night elf druids keep watch there. They guard the balance of nature in these mountains - and watch with worry what is happening further down." },
            { h = "Screaming saws", t = "The goblins of the Venture Co. cut down the forests as fast as their shredders can go. Where trees once stood, there are now stumps, rubble and oil. Whole valleys lie bare - and all the goblins count is their gold." },
            { h = "Harpies and tauren", t = "Harpies nest in the cliffs, and the Grimtotem clan of the tauren goes its own way here - not always peacefully. The Horde keeps a retreat in the mountains, the night elves their peak. And a path deep through the mountain leads over into Ashenvale." },
        },
    },
    [1437] = { wiki = "Wetlands",
        de = {
            { h = "Der Hafen von Menethil", t = "Der Hafen von Menethil wurde einst von Lordaeron gegründet und trägt den Namen seines Königshauses. Seit dem Fall Lordaerons ist er einer der letzten Häfen der Menschen im Norden. Schiffe fahren nach Theramore und zur Dunkelküste, und im Gasthaus hört man Geschichten aus allen Ecken der Welt." },
            { h = "Grim Batol", t = "Im Osten ragt Grim Batol auf, einst die Heimat der Wildhammerzwerge. Nach einem alten Krieg verließen sie die Festung, die seitdem als verflucht gilt. Später hielt der Drachenmalclan der Orcs dort Alexstrasza gefangen, die Königin der roten Drachen, und zwang ihre Jungen in den Krieg." },
            { h = "Die Thandolbrücke", t = "Im Norden spannt sich die Thandolbrücke über eine tiefe Schlucht und verbindet Khaz Modan mit dem Arathihochland. Doch an ihrem Fuß haben sich Dunkeleisenzwerge in der alten Festung Dun Modr festgesetzt. Wer nach Norden will, hält besser die Augen offen." },
        },
        en = {
            { h = "Menethil Harbor", t = "Menethil Harbor was once founded by Lordaeron and carries the name of its royal house. Since Lordaeron fell, it is one of the last human harbors in the north. Ships sail to Theramore and Darkshore, and in the inn you hear stories from every corner of the world." },
            { h = "Grim Batol", t = "To the east rises Grim Batol, once home of the Wildhammer dwarves. After an old war they left the fortress, which has been considered cursed ever since. Later the orcs of the Dragonmaw clan held Alexstrasza captive there, queen of the red dragons, and forced her young into war." },
            { h = "Thandol Span", t = "In the north, Thandol Span arches over a deep gorge and links Khaz Modan with the Arathi Highlands. But at its foot, Dark Iron dwarves have dug in at the old fortress of Dun Modr. Anyone heading north should keep their eyes open." },
        },
    },
    [1424] = { wiki = "Hillsbrad_Foothills",
        de = {
            { h = "Zwei Dörfer, ein Tal", t = "Süderstade und Tarrens Mühle liegen nur einen kurzen Ritt auseinander - und doch trennt sie ein ganzer Krieg. In Süderstade hält die Allianz die Stellung, Tarrens Mühle gehört den Verlassenen. Seit die Verlassenen hier sind, wird zwischen den beiden Dörfern gekämpft." },
            { h = "Burg Durnholde", t = "In Burg Durnholde wuchs ein Orc-Junge als Sklave und Gladiator auf: Thrall. Sein Besitzer Aedelas Schwarzmoor wollte ihn zur Waffe formen. Nur ein Mädchen namens Taretha war gut zu ihm und half ihm bei der Flucht - und Thrall vergaß das nie. Heute ist die Burg ein Versteck des Syndikats." },
            { h = "Felder und Fischer", t = "Bevor die Seuche kam, war das Hügelland eine ruhige Gegend voller Felder, Obstgärten und Mühlen. Viele Höfe stehen heute leer. An der Küste leben Fischer mit Murlocs als ungeliebten Nachbarn, und in den Hügeln suchen Bergleute nach Erz." },
        },
        en = {
            { h = "Two villages, one valley", t = "Southshore and Tarren Mill are only a short ride apart - and yet a whole war lies between them. The Alliance holds out in Southshore, Tarren Mill belongs to the Forsaken. Ever since the Forsaken arrived, the two villages have been fighting." },
            { h = "Durnholde Keep", t = "At Durnholde Keep, an orc boy grew up as a slave and gladiator: Thrall. His owner Aedelas Blackmoore wanted to shape him into a weapon. Only a girl named Taretha was kind to him and helped him escape - and Thrall never forgot it. Today the keep is a hideout of the Syndicate." },
            { h = "Fields and fishermen", t = "Before the plague came, Hillsbrad was a quiet land of fields, orchards and mills. Many farms stand empty today. Along the coast, fishermen live with murlocs as unloved neighbors, and in the hills miners search for ore." },
        },
    },
    [1441] = { wiki = "Thousand_Needles",
        de = {
            { h = "Ein Wald aus Stein", t = "Die Tausend Nadeln sind gewaltige Felstürme, die aus einer tiefen, trockenen Senke ragen. Wind und Wasser haben sie über eine Ewigkeit geformt. Zwischen manchen spannen sich Hängebrücken, und oben nisten Windreiter und Vögel - ein schwindelerregender Anblick." },
            { h = "Rennen auf dem Salz", t = "Im Osten liegen die Schimmernden Ebenen, ein ausgetrockneter Salzsee. Hier haben Goblins und Gnome eine Rennstrecke gebaut und lassen ihre lauten Rennwagen gegeneinander antreten. Wer gewinnt, ist fast egal - Hauptsache, es knallt und qualmt." },
            { h = "Freiwind und die Grimmtotem", t = "Auf einem hohen Plateau liegt der Freiwindposten der Tauren, erreichbar über steile Pfade und Brücken. Doch die Tauren hier haben Sorgen: Der Grimmtotem-Klan beansprucht die Nadeln für sich, und Zentauren ziehen durch die Schluchten." },
        },
        en = {
            { h = "A forest of stone", t = "The Thousand Needles are huge towers of rock rising from a deep, dry basin. Wind and water shaped them over ages. Rope bridges stretch between some of them, and high up wind riders and birds nest - a dizzying sight." },
            { h = "Racing on the salt", t = "In the east lie the Shimmering Flats, a dried-up salt lake. Goblins and gnomes have built a race track here and pit their loud racers against each other. Who wins hardly matters - as long as there is a bang and plenty of smoke." },
            { h = "Freewind and the Grimtotem", t = "On a high plateau lies the tauren's Freewind Post, reached by steep paths and bridges. But the tauren here have worries: the Grimtotem clan claims the Needles for itself, and centaur roam the canyons." },
        },
    },
    [1416] = { wiki = "Alterac_Mountains",
        de = {
            { h = "Ein verspieltes Königreich", t = "Alterac war einst ein Königreich der Menschen. Im Zweiten Krieg verriet König Perenolde die Allianz an die Horde - danach war Alterac am Ende. Die Burgen verfielen, und Oger zogen in die Ruinen der Hauptstadt." },
            { h = "Das Syndikat", t = "Viele Adlige Alteracs wollten ihren Rang nicht aufgeben. Sie gründeten das Syndikat, eine Bande aus Dieben, Schmugglern und Mördern, die von Alterac bis ins Arathihochland reicht. Sie träumen davon, eines Tages wieder zu herrschen." },
            { h = "Dalaran und Rabenholdt", t = "Am Rand der Berge liegt Dalaran, die Stadt der Magier. Im Dritten Krieg zerstörte der Dämon Archimonde sie, heute bauen die Kirin Tor sie hinter einer violetten Kuppel wieder auf. Ganz anders Rabenholdt: Das Anwesen in den Bergen ist so gut versteckt, dass es nur findet, wen die Schurken dort haben wollen." },
        },
        en = {
            { h = "A kingdom thrown away", t = "Alterac was once a human kingdom. In the Second War, King Perenolde betrayed the Alliance to the Horde - and that was the end of Alterac. The castles crumbled, and ogres moved into the ruins of the capital." },
            { h = "The Syndicate", t = "Many of Alterac's nobles refused to give up their rank. They founded the Syndicate, a gang of thieves, smugglers and killers that reaches from Alterac into the Arathi Highlands. They dream of ruling again one day." },
            { h = "Dalaran and Ravenholdt", t = "At the edge of the mountains lies Dalaran, the city of mages. In the Third War the demon Archimonde destroyed it; today the Kirin Tor are rebuilding it behind a violet dome. Ravenholdt is the opposite: the manor in the mountains is so well hidden that only those the rogues want there ever find it." },
        },
    },
    [1417] = { wiki = "Arathi_Highlands",
        de = {
            { h = "Das erste Reich", t = "Hier begann die Geschichte der Menschen: Thoradin einte die Stämme und gründete Arathor mit der Hauptstadt Strom. Im Krieg gegen die Trolle verbündete sich Arathor mit den Hochelfen, die hundert Menschen in die Magie einweihten. Aus diesem Bund wuchs die Magie der Menschen." },
            { h = "Stromgarde", t = "Stromgarde sieht sich als Erbe des alten Arathor. Doch die Festung ist halb zerstört, und um ihre Mauern streiten Oger, das Syndikat und die Verlassenen. Die letzten Soldaten Stromgardes halten aus - stolz, müde und ohne viel Hilfe." },
            { h = "Trolle und Steinkreise", t = "In den Hügeln leben Waldtrolle, alte Feinde der Menschen seit den Tagen von Arathor. Rätselhafte Steinkreise stehen auf den Wiesen, und kaum jemand weiß noch, wer sie errichtet hat. Im Arathibecken kämpfen Allianz und Horde um Höfe, Minen und Sägewerke." },
        },
        en = {
            { h = "The first kingdom", t = "This is where the story of humankind began: Thoradin united the tribes and founded Arathor with its capital Strom. In the war against the trolls, Arathor allied with the high elves, who taught magic to a hundred humans. Human magic grew from that bond." },
            { h = "Stromgarde", t = "Stromgarde sees itself as heir to ancient Arathor. But the fortress is half in ruins, and ogres, the Syndicate and the Forsaken fight over its walls. Stromgarde's last soldiers hold out - proud, tired and without much help." },
            { h = "Trolls and stone circles", t = "Forest trolls live in the hills, enemies of humankind since the days of Arathor. Mysterious stone circles stand in the meadows, and hardly anyone remembers who raised them. In Arathi Basin, Alliance and Horde fight over farms, mines and lumber mills." },
        },
    },
    [1443] = { wiki = "Desolace",
        de = {
            { h = "Die Zentaurenkriege", t = "Desolace ist das Land der Zentauren. Ihre Stämme - Magram, Gelkis, Kolkar und andere - führen seit Generationen Krieg gegeneinander. Wer sich hier einmischt, macht sich bei einem Stamm Freunde und beim nächsten Feinde." },
            { h = "Das Grab des Zaetar", t = "Der Sage nach stammen die Zentauren von Zaetar ab, einem Sohn des Halbgotts Cenarius, und der Erdprinzessin Theradras. Ihre eigenen Kinder erschlugen Zaetar. Theradras begrub ihn tief in Maraudon - und noch heute irrt sein Geist durch das Land." },
            { h = "Alte Spuren", t = "In Desolace liegen die Knochen gewaltiger Kodos, die zum Sterben hierher wandern. Auch Dämonen der Brennenden Legion und Kultisten der Brennenden Klinge haben sich eingenistet. Allianz und Horde halten hier nur kleine Posten - es ist ein raues Land für alle." },
        },
        en = {
            { h = "The centaur wars", t = "Desolace is the land of the centaur. Their tribes - Magram, Gelkis, Kolkar and others - have been at war with each other for generations. Whoever gets involved here makes friends with one tribe and enemies of the next." },
            { h = "Zaetar's tomb", t = "Legend says the centaur descend from Zaetar, a son of the demigod Cenarius, and the earth princess Theradras. Their own children slew Zaetar. Theradras buried him deep in Maraudon - and his spirit still wanders the land." },
            { h = "Old traces", t = "Desolace holds the bones of giant kodos who wander here to die. Demons of the Burning Legion and cultists of the Burning Blade have settled in too. Alliance and Horde keep only small outposts here - it is a harsh land for everyone." },
        },
    },
    [1434] = { wiki = "Stranglethorn_Vale",
        de = {
            { h = "Das Reich der Gurubashi", t = "Einst herrschten die Gurubashi-Trolle über diesen Dschungel. Um ihre Macht zu sichern, riefen ihre Priester den Blutgott Hakkar - und er verlangte immer mehr Opfer. Daran zerbrach das Reich. Heute überwuchert der Dschungel ihre Tempel, und in Zul'Gurub regt sich das Böse erneut." },
            { h = "Beutebucht", t = "Ganz im Süden liegt die Beutebucht, eine Goblinstadt, in die Felsen rund um eine geschützte Bucht gebaut. Hier zählt nur Gold: Jeder darf handeln, solange er sich benimmt - die Wachen des Dampfdruckkartells sorgen dafür. Draußen auf See lauern die Piraten der Blutsegel." },
            { h = "Jäger und Abtrünnige", t = "Im Norden hat Hemet Nesingwary sein Lager und lädt Jäger ein, Tiger, Panther und Raptoren zu erlegen. Tiefer im Dschungel hat sich eine Truppe ehemaliger Soldaten Sturmwinds unter Oberst Kurzen von ihrem Königreich losgesagt. Im Schlingendorntal ist niemand ganz, was er scheint." },
        },
        en = {
            { h = "The Gurubashi empire", t = "The Gurubashi trolls once ruled this jungle. To secure their power, their priests called upon the blood god Hakkar - and he demanded ever more sacrifices. The empire broke apart. Today the jungle grows over their temples, and in Zul'Gurub evil stirs once more." },
            { h = "Booty Bay", t = "At the very south lies Booty Bay, a goblin town built into the cliffs around a sheltered bay. Only gold counts here: anyone may trade as long as they behave - the guards of the Steamwheedle Cartel make sure of it. Out at sea, the pirates of the Bloodsail lie in wait." },
            { h = "Hunters and renegades", t = "In the north, Hemet Nesingwary keeps his camp and invites hunters to bring down tigers, panthers and raptors. Deeper in the jungle, a band of former Stormwind soldiers under Colonel Kurzen has broken away from their kingdom. In Stranglethorn, nobody is quite what they seem." },
        },
    },
    [1435] = { wiki = "Swamp_of_Sorrows",
        de = {
            { h = "Der versunkene Tempel", t = "Die Atal'ai-Trolle bauten tief im Sumpf einen Tempel für den Blutgott Hakkar. Als sie ihn in die Welt holen wollten, griff Ysera ein, der Aspekt der grünen Drachen, und ließ den Tempel im Sumpf versinken. Grüne Drachen bewachen ihn bis heute." },
            { h = "Steinard", t = "Steinard ist die Festung der Horde im Süden der Östlichen Königreiche, mitten im Sumpf. Von hier behalten die Orcs das Land der Allianz im Auge - und die nahen Verwüsteten Lande mit dem Dunklen Portal. Gemütlich ist es nicht, aber sicher." },
            { h = "Nebel und Trauer", t = "Der Sumpf trägt seinen Namen nicht ohne Grund: Nebel, Regen und dunkles Wasser lasten auf dem Land. Krokilisken lauern an den Ufern, und in den Tälern leben die Verlorenen, ein heimatloses Volk von weit her." },
        },
        en = {
            { h = "The sunken temple", t = "Deep in the swamp, the Atal'ai trolls built a temple to the blood god Hakkar. When they tried to bring him into the world, Ysera, Aspect of the green dragons, stepped in and sank the temple into the swamp. Green dragons guard it to this day." },
            { h = "Stonard", t = "Stonard is the Horde's stronghold in the south of the Eastern Kingdoms, in the middle of the swamp. From here the orcs keep an eye on Alliance lands - and on the nearby Blasted Lands with the Dark Portal. It is not cozy, but it is safe." },
            { h = "Mist and sorrow", t = "The swamp did not get its name for nothing: mist, rain and dark water weigh on the land. Crocolisks lurk along the banks, and in the valleys live the Lost Ones, a homeless people from far away." },
        },
    },
    [1445] = { wiki = "Dustwallow_Marsh",
        de = {
            { h = "Theramore", t = "Theramore ist die Stadt von Jaina Prachtmeer. Sie führte Flüchtlinge aus Lordaeron nach Kalimdor und baute hier, auf einer Insel vor der Küste, eine neue Heimat. Jaina sucht den Frieden mit der Horde - nicht alle in ihrer Stadt sehen das gern." },
            { h = "Todesschwinges Tochter", t = "Tief in den Marschen liegt Onyxias Hort. Onyxia ist die Tochter von Todesschwinge, dem Anführer der schwarzen Drachen. Es heißt, sie zeige sich auch in Menschengestalt - und habe so bis an den Hof von Sturmwind Einfluss gewonnen." },
            { h = "Sumpf, Hexen und Angeln", t = "Die Horde hat in den Marschen ein Dorf, mitten zwischen Schlamm und Schilf. Auf einem Hügel soll eine Hexe hausen, und überall lauern Krokilisken und Drachenbrut. Und irgendwo am Wasser sitzt Nat Pagle, der berühmteste Angler der Welt, und wartet auf den großen Fang." },
        },
        en = {
            { h = "Theramore", t = "Theramore is Jaina Proudmoore's city. She led refugees from Lordaeron to Kalimdor and built a new home here, on an island off the coast. Jaina seeks peace with the Horde - not everyone in her city likes that." },
            { h = "Deathwing's daughter", t = "Deep in the marsh lies Onyxia's Lair. Onyxia is the daughter of Deathwing, leader of the black dragons. They say she also walks in human form - and has gained influence that way all the way to the court of Stormwind." },
            { h = "Swamp, witches and fishing rods", t = "The Horde has a village in the marsh, right among mud and reeds. A witch is said to live on a hill, and crocolisks and dragonkin lurk everywhere. And somewhere by the water sits Nat Pagle, the most famous angler in the world, waiting for the big catch." },
        },
    },
    [1418] = { wiki = "Badlands",
        de = {
            { h = "Uldaman", t = "Unter den Felsen des Ödlands liegt Uldaman, ein Gewölbe aus der Zeit der Titanen. Die Forscherliga gräbt hier nach der Herkunft der Zwerge - und Dunkeleisenzwerge und Troggs graben mit, jeder auf eigene Rechnung. Was die Titanen dort zurückließen, ist nicht ganz ungefährlich." },
            { h = "Kargath", t = "Der Horde-Posten Kargath trägt den Namen von Kargath Messerfaust, dem Häuptling der Zerschmetterten Hand, der sich einst selbst eine Hand abschlug und eine Klinge an ihre Stelle setzte. Von hier aus behält die Horde den Weg zur Sengenden Schlucht im Blick." },
            { h = "Drachen und Staub", t = "Das Ödland ist trocken, rot und rissig, und die Sonne brennt. Über einer Schlucht kreisen schwarze Drachen, Oger hausen in den Hügeln, und Dunkeleisenzwerge haben sich im Fels verschanzt. Wer hier Rast macht, sucht sich besser einen Platz mit dem Rücken zur Wand." },
        },
        en = {
            { h = "Uldaman", t = "Beneath the rocks of the Badlands lies Uldaman, a vault from the age of the titans. The Explorers' League digs here for the origins of the dwarves - and Dark Iron dwarves and troggs dig too, each for themselves. What the titans left behind is not entirely harmless." },
            { h = "Kargath", t = "The Horde outpost of Kargath carries the name of Kargath Bladefist, chieftain of the Shattered Hand, who once cut off his own hand and put a blade in its place. From here the Horde keeps watch on the road to the Searing Gorge." },
            { h = "Dragons and dust", t = "The Badlands are dry, red and cracked, and the sun burns down. Black dragons circle above a ravine, ogres live in the hills, and Dark Iron dwarves have dug into the rock. Anyone resting here had better pick a spot with their back to the wall." },
        },
    },
}
